-- =====================================================================
--  데모 데이터 (seed-demo.sql)
-- =====================================================================
--
--  🔴 **운영 DB 에 실행하지 마라.** 이 파일은 빈 데이터베이스를 화면 구경용으로
--     채우기 위한 것이다. 학년 6개 · 반 13개 · 강사 4명 ·
--     학생 40명과 그에 딸린 납부·청구·출결·특강·지출 샘플이 들어간다.
--
--  이름은 전부 **널리 알려진 연예인·스포츠 스타의 예명**이고, 전화번호는
--  010-0000-XXXX 형태의 명백한 가짜다. 실존 학생 정보는 한 건도 없다.
--
--  실행 방법
--  ---------
--    supabase/schema.sql 을 **먼저** 실행한 뒤,
--    Supabase 대시보드 → SQL Editor 에 이 파일을 붙여넣고 Run.
--
--  기준 월은 2026-08 이다. 다른 달로 보고 싶으면 아래 값들을 일괄 치환하면 된다.
--
--  지우기
--  ------
--    이 파일 맨 아래 주석에 정리용 DELETE 문이 있다.
--    데모 행은 id 가 전부 '00000000-0000-4000-8000-...' 로 시작하므로 그것으로 골라낸다.
--
--  ⚠️ 모든 INSERT 에 ON CONFLICT DO NOTHING 이 붙어 있어 여러 번 실행해도 안전하다.
-- =====================================================================

BEGIN;


-- ── 학년 ──
ON CONFLICT DO NOTHING;


-- ── 강사 ── (pay_ratio = 급여 배분율 %)
ON CONFLICT DO NOTHING;


-- ── 반 ── (반 신원 = 학년 + 과목 + 반이름)
ON CONFLICT DO NOTHING;


-- ── 학생 ──
--  섞여 있는 케이스들(일부러 넣었다 — 화면에서 각각 다르게 보인다):
--    · custom_fee = 0        면제 학생 (청구·미납 집계에서 빠진다)
--    · custom_fee = 350000   반 정가와 다른 개별 요금
--    · withdrawal_date       월중 퇴원 (그 달 명단엔 남고 다음 달엔 빠진다)
--    · batch_exclude_month   그 달만 일괄 청구 제외 (요금 면제가 아님에 주의)
--    · electives             선택과목 수강 → 총 수업료 = 반 원비 + 과목 요금
--    · split_billing_*       청구서 2건 분할 발송
ON CONFLICT DO NOTHING;


-- ── 납부 기록 ── (2026-08 약 70% 완납 + 2026-07 일부)
ON CONFLICT DO NOTHING;


-- ── 청구서 이력 ── (status: sent 발송됨 / paid 결제완료 / destroyed 파기)
ON CONFLICT DO NOTHING;


-- ── 요금 스냅샷 ── (그 달의 '확정 요금'. 나중에 반 원비가 바뀌어도 과거 달 판정이 흔들리지 않게 박아둔다)
ON CONFLICT DO NOTHING;


-- ── 출결 ── (2026-08-31 하루치. present 출석 / late 지각 / early_leave 조퇴 / absent 결석 / makeup 보강)
ON CONFLICT DO NOTHING;


-- ── 특강 ── (정규와 별개로 기간을 정해 여는 수업)
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;


-- ── 학원 지출 ── (재무 화면의 손익 계산에 쓰인다)
ON CONFLICT DO NOTHING;


-- ── 월별 메모 ── (납부 화면 상단에 붙는 자유 메모)
ON CONFLICT DO NOTHING;


-- ── 감사 로그 ── (돈·학생 정보를 바꾼 모든 행위가 쌓인다. 지우지 않는다)
ON CONFLICT DO NOTHING;


COMMIT;


